-- music.artists
CREATE TRIGGER "music.artists_sync_canonical_artist_to_learning_update" AFTER UPDATE OF "display_name", "profile_image_asset_id", "publication_status", "owner_creator_account_id" ON "music.artists"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (OLD."display_name" IS NOT NEW."display_name" OR OLD."profile_image_asset_id" IS NOT NEW."profile_image_asset_id" OR OLD."publication_status" IS NOT NEW."publication_status" OR OLD."owner_creator_account_id" IS NOT NEW."owner_creator_account_id")
BEGIN
  UPDATE "learning.cantors" SET "display_name" = NEW."display_name", "profile_image_asset_id" = NEW."profile_image_asset_id",
      "publication_status" = CASE WHEN NEW."publication_status" = 'published' OR NEW."is_credit_only" THEN 'published' ELSE "publication_status" END,
      "updated_at" = (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00')
    WHERE "artist_id" = NEW."id"
      AND ("display_name" IS NOT NEW."display_name" OR "profile_image_asset_id" IS NOT NEW."profile_image_asset_id"
        OR (NEW."publication_status" = 'published' AND "publication_status" <> 'published'));
END;
