-- music.release_tracks
CREATE TRIGGER "music.release_tracks_release_tracks_sync_release_type_insert" AFTER INSERT ON "music.release_tracks"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0)
BEGIN
  UPDATE "music.releases" SET "release_type" = (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END), "updated_at" = (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00')
    WHERE "id" = NEW."release_id" AND (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") > 0 AND "release_type" IS NOT (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END);
END;
CREATE TRIGGER "music.release_tracks_release_tracks_sync_release_type_update" AFTER UPDATE OF "release_id" ON "music.release_tracks"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0)
BEGIN
  UPDATE "music.releases" SET "release_type" = (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END), "updated_at" = (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00')
    WHERE "id" = NEW."release_id" AND (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") > 0 AND "release_type" IS NOT (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = NEW."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END);
  UPDATE "music.releases" SET "release_type" = (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END), "updated_at" = (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00')
    WHERE "id" = OLD."release_id" AND (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") > 0 AND "release_type" IS NOT (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END) AND OLD."release_id" IS NOT NEW."release_id";
END;
CREATE TRIGGER "music.release_tracks_release_tracks_sync_release_type_delete" AFTER DELETE ON "music.release_tracks"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0)
BEGIN
  UPDATE "music.releases" SET "release_type" = (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END), "updated_at" = (rtrim(rtrim(strftime('%Y-%m-%dT%H:%M:%f', 'now'), '0'), '.') || '+00:00')
    WHERE "id" = OLD."release_id" AND (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") > 0 AND "release_type" IS NOT (CASE WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") = 1 THEN 'single' WHEN (SELECT count(*) FROM "music.release_tracks" rt WHERE rt."release_id" = OLD."release_id") BETWEEN 2 AND 6 THEN 'ep' ELSE 'album' END);
END;

-- music.releases
CREATE TRIGGER "music.releases_releases_enforce_scheduling_window_insert" BEFORE INSERT ON "music.releases"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (NEW."scheduled_release_at" IS NOT NULL)
BEGIN
  SELECT RAISE(ABORT, 'pg:22023:' || 'A release must be scheduled at least 48 hours out (earliest ' || strftime('%Y-%m-%d %H:00', 'now', '+48 hours') || ' UTC)')
    WHERE NEW."scheduled_release_at" < strftime('%Y-%m-%dT%H:00:00', 'now', '+48 hours') || '+00:00';
END;
CREATE TRIGGER "music.releases_releases_enforce_scheduling_window_update" BEFORE UPDATE OF "scheduled_release_at" ON "music.releases"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (NEW."scheduled_release_at" IS NOT NULL AND OLD."scheduled_release_at" IS NOT NEW."scheduled_release_at")
BEGIN
  SELECT RAISE(ABORT, 'pg:22023:' || 'A release must be scheduled at least 48 hours out (earliest ' || strftime('%Y-%m-%d %H:00', 'now', '+48 hours') || ' UTC)')
    WHERE NEW."scheduled_release_at" < strftime('%Y-%m-%dT%H:00:00', 'now', '+48 hours') || '+00:00';
END;
CREATE TRIGGER "music.releases_releases_enforce_identity_artist_insert" BEFORE INSERT ON "music.releases"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (NEW."owner_creator_account_id" IS NOT NULL AND NEW."primary_artist_id" IS NOT NULL)
BEGIN
  SELECT RAISE(ABORT, 'pg:22023:' || 'Creator account ' || coalesce((SELECT a."display_name" FROM "creator.creator_accounts" a WHERE a."id" = NEW."owner_creator_account_id"), NEW."owner_creator_account_id") || ' has no artist identity yet') WHERE (SELECT a."identity_artist_id" FROM "creator.creator_accounts" a WHERE a."id" = NEW."owner_creator_account_id") IS NULL;
  SELECT RAISE(ABORT, 'pg:42501:' || 'A release can only be published under its own account''s artist identity') WHERE NEW."primary_artist_id" <> (SELECT a."identity_artist_id" FROM "creator.creator_accounts" a WHERE a."id" = NEW."owner_creator_account_id");
END;
CREATE TRIGGER "music.releases_releases_enforce_identity_artist_update" BEFORE UPDATE OF "owner_creator_account_id", "primary_artist_id" ON "music.releases"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (NEW."owner_creator_account_id" IS NOT NULL AND NEW."primary_artist_id" IS NOT NULL)
BEGIN
  SELECT RAISE(ABORT, 'pg:22023:' || 'Creator account ' || coalesce((SELECT a."display_name" FROM "creator.creator_accounts" a WHERE a."id" = NEW."owner_creator_account_id"), NEW."owner_creator_account_id") || ' has no artist identity yet') WHERE (SELECT a."identity_artist_id" FROM "creator.creator_accounts" a WHERE a."id" = NEW."owner_creator_account_id") IS NULL;
  SELECT RAISE(ABORT, 'pg:42501:' || 'A release can only be published under its own account''s artist identity') WHERE NEW."primary_artist_id" <> (SELECT a."identity_artist_id" FROM "creator.creator_accounts" a WHERE a."id" = NEW."owner_creator_account_id");
END;
CREATE TRIGGER "music.releases_notify_release_published_insert" AFTER INSERT ON "music.releases"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (NEW."publication_status" = 'published')
BEGIN
  UPDATE "private.trigger_marks" SET "value" = (SELECT coalesce(max(rowid), 0) FROM "public.notifications") WHERE "name" = 'notifications';
  INSERT INTO "public.notifications" ("user_id", "app_key", "category", "event_type", "title", "body", "deep_link", "image_url", "payload")
    SELECT audience."user_id", 'chc', 'followed_artists', 'release_published', 'New from ' || coalesce((SELECT a."display_name" FROM "music.artists" a WHERE a."id" = NEW."primary_artist_id"), 'Coptic Vine'), NEW."title" || ' is now available on Coptic Vine.', '/music/release/' || NEW."id", NULL, '{' || '"artist_id": ' || json_quote(NEW."primary_artist_id") || ', "release_id": ' || json_quote(NEW."id") || '}'
    FROM (SELECT f."user_id" FROM "music.artist_follows" f WHERE f."artist_id" = NEW."primary_artist_id") audience
    WHERE audience."user_id" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "public.notification_preferences" pref
      WHERE pref."user_id" = audience."user_id" AND pref."app_key" = 'chc' AND pref."category" = 'followed_artists' AND pref."enabled" = 0);
  INSERT INTO "private.notification_deliveries" ("notification_id", "device_id", "provider")
    SELECT n."id", d."id", d."provider" FROM "public.notifications" n
    JOIN "public.notification_devices" d ON d."user_id" = n."user_id" AND d."app_key" = n."app_key" AND d."enabled" = 1 AND d."provider" IN ('expo', 'web_push')
    WHERE n.rowid > (SELECT "value" FROM "private.trigger_marks" WHERE "name" = 'notifications')
    ON CONFLICT ("notification_id", "device_id") DO NOTHING;
  UPDATE "private.trigger_marks" SET "value" = (SELECT coalesce(max(rowid), 0) FROM "public.notifications") WHERE "name" = 'notifications';
  INSERT INTO "public.notifications" ("user_id", "app_key", "category", "event_type", "title", "body", "deep_link", "image_url", "payload")
    SELECT audience."user_id", 'chc_artists', 'release_updates', 'release_published', 'Release is live', NEW."title" || ' is now available on Coptic Vine.', '/release/' || NEW."id", NULL, '{' || '"release_id": ' || json_quote(NEW."id") || '}'
    FROM (SELECT DISTINCT m."user_id" FROM "creator.creator_account_members" m WHERE m."creator_account_id" = NEW."owner_creator_account_id") audience
    WHERE audience."user_id" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "public.notification_preferences" pref
      WHERE pref."user_id" = audience."user_id" AND pref."app_key" = 'chc_artists' AND pref."category" = 'release_updates' AND pref."enabled" = 0);
  INSERT INTO "private.notification_deliveries" ("notification_id", "device_id", "provider")
    SELECT n."id", d."id", d."provider" FROM "public.notifications" n
    JOIN "public.notification_devices" d ON d."user_id" = n."user_id" AND d."app_key" = n."app_key" AND d."enabled" = 1 AND d."provider" IN ('expo', 'web_push')
    WHERE n.rowid > (SELECT "value" FROM "private.trigger_marks" WHERE "name" = 'notifications')
    ON CONFLICT ("notification_id", "device_id") DO NOTHING;
END;
CREATE TRIGGER "music.releases_notify_release_published_update" AFTER UPDATE OF "publication_status" ON "music.releases"
FOR EACH ROW WHEN ((SELECT "depth" FROM "private.replica_mode") = 0) AND (NEW."publication_status" = 'published' AND OLD."publication_status" <> 'published')
BEGIN
  UPDATE "private.trigger_marks" SET "value" = (SELECT coalesce(max(rowid), 0) FROM "public.notifications") WHERE "name" = 'notifications';
